-- Existing package state belongs to the original default department.
ALTER TABLE harbor.account_package_templates ADD COLUMN department_id TEXT;
ALTER TABLE harbor.account_package_versions ADD COLUMN department_id TEXT;
ALTER TABLE harbor.account_package_selections ADD COLUMN department_id TEXT;
ALTER TABLE harbor.account_package_previews ADD COLUMN department_id TEXT;
ALTER TABLE harbor.account_package_previews ADD COLUMN actor_kind TEXT;
ALTER TABLE harbor.account_package_previews ADD COLUMN actor_id TEXT;
ALTER TABLE harbor.account_package_previews ADD COLUMN actor_version BIGINT;
UPDATE harbor.account_package_templates SET department_id='department-default';
UPDATE harbor.account_package_versions SET department_id='department-default';
UPDATE harbor.account_package_selections s SET department_id=a.department_id FROM harbor.accounts a WHERE a.id=s.account_id;
UPDATE harbor.account_package_previews SET department_id='department-default',actor_kind='legacy_admin',actor_id='migration-v1',actor_version=0;
ALTER TABLE harbor.account_package_templates ALTER COLUMN department_id SET NOT NULL;
ALTER TABLE harbor.account_package_versions ALTER COLUMN department_id SET NOT NULL;
ALTER TABLE harbor.account_package_selections ALTER COLUMN department_id SET NOT NULL;
ALTER TABLE harbor.account_package_previews ALTER COLUMN department_id SET NOT NULL;
ALTER TABLE harbor.account_package_previews ALTER COLUMN actor_kind SET NOT NULL;
ALTER TABLE harbor.account_package_previews ALTER COLUMN actor_id SET NOT NULL;
ALTER TABLE harbor.account_package_previews ALTER COLUMN actor_version SET NOT NULL;
ALTER TABLE harbor.account_package_templates ADD CONSTRAINT department_package_templates_fk FOREIGN KEY(department_id) REFERENCES harbor.departments(id);
ALTER TABLE harbor.account_package_templates ADD CONSTRAINT department_package_templates_identity UNIQUE(department_id,id);
ALTER TABLE harbor.account_package_versions ADD CONSTRAINT department_package_versions_fk FOREIGN KEY(department_id,template_id) REFERENCES harbor.account_package_templates(department_id,id);
ALTER TABLE harbor.account_package_versions ADD CONSTRAINT department_package_versions_identity UNIQUE(department_id,template_id,version);
ALTER TABLE harbor.account_package_selections ADD CONSTRAINT department_package_account_fk FOREIGN KEY(department_id,account_id) REFERENCES harbor.accounts(department_id,id);
ALTER TABLE harbor.account_package_selections ADD CONSTRAINT department_package_selection_fk FOREIGN KEY(department_id,template_id,template_version) REFERENCES harbor.account_package_versions(department_id,template_id,version);
ALTER TABLE harbor.account_package_previews ADD CONSTRAINT department_package_previews_fk FOREIGN KEY(department_id) REFERENCES harbor.departments(id);
ALTER TABLE harbor.account_package_previews ADD CONSTRAINT department_package_preview_actor CHECK(actor_kind IN ('super_admin','department_admin','legacy_admin') AND length(actor_id)>0 AND actor_version>=0);
CREATE INDEX department_package_templates_page ON harbor.account_package_templates(department_id,id);
CREATE INDEX department_package_previews_page ON harbor.account_package_previews(department_id,created DESC,id DESC);
CREATE TRIGGER department_identity_immutable BEFORE UPDATE OF department_id ON harbor.account_package_templates FOR EACH ROW EXECUTE FUNCTION harbor.department_identity_immutable();
CREATE TRIGGER department_identity_immutable BEFORE UPDATE OF department_id ON harbor.account_package_versions FOR EACH ROW EXECUTE FUNCTION harbor.department_identity_immutable();
CREATE TRIGGER department_identity_immutable BEFORE UPDATE OF department_id ON harbor.account_package_selections FOR EACH ROW EXECUTE FUNCTION harbor.department_identity_immutable();
CREATE TRIGGER department_identity_immutable BEFORE UPDATE OF department_id ON harbor.account_package_previews FOR EACH ROW EXECUTE FUNCTION harbor.department_identity_immutable();
CREATE TRIGGER department_batch_actor_immutable BEFORE UPDATE OF actor_kind,actor_id,actor_version ON harbor.account_package_previews FOR EACH ROW EXECUTE FUNCTION harbor.department_batch_actor_immutable();
